[Outro]
To him we call
The Lord of all
The Lord of all
There is one who gives
The right to be 
The right to live
There is one who gives
The right to breath
The right to death
To him we call
The Lord of all'), ('1fa99e66-f19f-4b13-a0ea-8a690979985d', 'Guide Me', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/The+One+Production/Guide+Me.opus', '9f762764-9956-40a7-97d4-77b166bd01de', '63093b24-b2dd-4e0e-991a-2a1268180589', null, true, null), ('2121b693-a639-4265-8399-cf779564433d', 'Alhamdullilah Rabbil Aalameen', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/Vaaleh/Alhamdullilah+Rabbil+Aalameen.mp3', 'a715354d-7579-4b09-9d12-11c38778f970', 'b0c08d00-c24b-4b26-9ce8-0197537bed3f', null, false, null), ('232531b4-2ebf-417a-988f-cc7f7bc48b41', '7 Spikes of Grace', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/Equalizer/7+Spikes+of+Grace.mp3', '121e45a0-fd68-4f98-abed-7f515e987252', 'bb8390f2-6eb6-402e-b068-43b57a4fb2da', null, false, null), ('266a7073-2efb-4cc0-bb18-206740992894', 'The Living The Eternal', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/Monotheist+Melodies/The+Living+The+Eternal.mp3', 'b608abbf-e3b4-4a2a-9475-522dd0ec25c8', '63093b24-b2dd-4e0e-991a-2a1268180589', null, false, null), ('29df292b-fd6b-47e8-8cfd-969575743704', 'Lā ilāha illa Allāh', '2025-12-07', 'https://cdn.wikisubmission.org/media/zikr/The+One+Production/L%C4%81+il%C4%81ha+illa+All%C4%81h.mp3', '9f762764-9956-40a7-97d4-77b166bd01de', '63093b24-b2dd-4e0e-991a-2a1268180589', null, true, null), ('2a4ef11d-b4a2-43f3-853b-5339b9771d58', 'The Key', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/The+One+Production/The+Key.opus', '9f762764-9956-40a7-97d4-77b166bd01de', '63093b24-b2dd-4e0e-991a-2a1268180589', null, false, null), ('2ce43ea8-af73-4ac2-aad1-7fb8a85ac0cf', 'Most Gracious', '2026-01-07', 'https://cdn.wikisubmission.org/media/zikr/Kolob/Most Gracious.mp3', '6503ba13-a973-4f68-b90f-9a6bc89e4825', '01ac864e-4512-4f6f-89d1-0ece0bf2039a', null, false, '[Verse 1]
