of Your servants.
You are always near.'), ('64400a00-1a59-4801-8524-1575ed9460d5', 'هر سختی، رشد است', '2025-12-05', 'https://cdn.wikisubmission.org/media/zikr/Equalizer/%D9%87%D8%B1+%D8%B3%D8%AE%D8%AA%DB%8C%D8%8C+%D8%B1%D8%B4%D8%AF+%D8%A7%D8%B3%D8%AA.m4a', '121e45a0-fd68-4f98-abed-7f515e987252', 'fc53cb25-b452-4753-9e9b-34c72cfe146f', null, false, null), ('65b23386-f345-42c1-a401-0d135eba5815', 'In The Name of God', '2025-12-21', 'https://cdn.wikisubmission.org/media/zikr/Leen/In+The+Name+of+God.mp3', '68efa8ac-ccd8-4de7-909d-8cc347c15e78', '01ac864e-4512-4f6f-89d1-0ece0bf2039a', null, false, null), ('66322be0-dbcc-4c79-bb4e-83c498087955', 'Our Lord Watch Over Us', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/Vaaleh/Our+Lord+Watch+Over+Us.m4a', 'a715354d-7579-4b09-9d12-11c38778f970', 'b0c08d00-c24b-4b26-9ce8-0197537bed3f', null, false, null), ('7137d96b-bab4-40f2-876f-727cc8f71742', 'Allahu Akbar 1', '2025-01-01', 'https://cdn.wikisubmission.org/media/zikr/Vaaleh/Allahu+Akbar+1.mp3', 'a715354d-7579-4b09-9d12-11c38778f970', 'b0c08d00-c24b-4b26-9ce8-0197537bed3f', null, false, null), ('72e90827-c9b0-44bf-bfaf-76628fca7cd4', 'Recall Your Blessings', '2026-01-07', 'https://cdn.wikisubmission.org/media/zikr/Kolob/Recall Your Blessings.mp3', '6503ba13-a973-4f68-b90f-9a6bc89e4825', '01ac864e-4512-4f6f-89d1-0ece0bf2039a', null, false, 'Recall… recall…
